 \label{prop:T}
Let $X$ be a metric space. Assume $\diam{X} = 1$. For any $E \subseteq X$ and $\theta > 0$, $T^*_{E,\theta}$ has a predual $T_{E,\theta}: \LF{X} \to \LF{X}$ and
\begin{itemize}
\item $\|T^*_{E,\theta}\|,\|T_{E,\theta}\|$ are bounded by a function of $\theta$, $C(\theta)$ (independent of $E$).
\item For any $f \in \Lip{X}$ and $v \in \LFf{X}$, $\supp{T^*_{E,\theta}(f)} \subseteq \supp{f} \cap B_\theta(E)$ and $\supp{T_{E,\theta}(v)} \subseteq \supp{v} \cap B_\theta(E)$.
\item For any $v \in \LFf{X}$, $\supp{v-T_{E,\theta}(v)} \subseteq \supp{v} \setminus B_{\theta/2}(E)$.
\end{itemize}

Define ideals $\boldsymbol{\mathcal{F}in_n} \subseteq \Cl{X}$ recursively, as follows:
\begin{itemize}
\item $\mathcal{F}in_0 := \boldsymbol{\mathcal{F}in} :=$ finite subsets of $X$.
\item $\mathcal{F}in_{n+1} := \ulm{\mathcal{F}in_n}$.
\end{itemize}

\begin{equation} \label{eq:3c-1}
\rad{\mathcal{I}}{p}+\rad{\mathcal{I}}{q} < 3c^{-1}d(p,q).
\end{equation}

 \label{lem:sequence1}
Assume $X$ is discrete. Fix an ideal $\mathcal{I} \subseteq \Cl{X}$ such that $\mathcal{F}in \subseteq \mathcal{I}$ and $R^{\mathcal{I}}_{\mathcal{F}in}$ is injective. Set $\mathcal{J} := \ulm{\mathcal{I}}$ so that Theorem \ref{thm:injective} implies $R^{\mathcal{J}}_{\mathcal{F}in}$ is also injective (for example, $\mathcal{I} = \mathcal{F}in_n$ and $\mathcal{J} = \mathcal{F}in_{n+1}$). For any $p \in X$, $r \in (0,\rad{\mathcal{J}}{p})$, $u \in \LF{\mathcal{I}}{X}$ such that $\supp{u} \cap B_{r}(p)$ is finite, and sequence $v_n \in \LF{\mathcal{J}}{X}$ such that $\sup_n \|v_n\|_{\mathcal{J}} < 1$ and $R^{\mathcal{J}}_{\mathcal{I}}(v_n) \to u$, and $c \in (0,1)$, there exists another sequence $\tilde{v}_n$ such that
\begin{itemize}
\item $\sup_n \|\tilde{v}_n\|_{\mathcal{J}} < 1$,
\item $R^{\mathcal{J}}_{\mathcal{I}}(\tilde{v}_n) \to u$,
\item $\supp{\tilde{v}_n} \subseteq \supp{v_n}$,
\item and $\supp{\tilde{v}_n} \cap B_{cr}(p) = \supp{u} \cap B_{cr}(p)$.
\end{itemize}

 \label{lem:sequence2}
Assume $X$ is countable with enumeration $X = \{p_i\}_{i=1}^\infty$. Assume $X$ is discrete. Fix an ideal $\mathcal{I} \subseteq \Cl{X}$ such that $\mathcal{F}in \subseteq \mathcal{I}$ and $R^{\mathcal{I}}_{\mathcal{F}in}$ is injective. Set $\mathcal{J} := \ulm{\mathcal{I}}$ so that Theorem \ref{thm:injective} implies $R^{\mathcal{J}}_{\mathcal{F}in}$ is also injective (for example, $\mathcal{I} = \mathcal{F}in_n$ and $\mathcal{J} = \mathcal{F}in_{n+1}$). For any collection of radii $\{r_p\}_{p \in X}$ with $r_p \in (0,\rad{\mathcal{J}}{p})$, $u \in \LF{\mathcal{I}}{X}$ such that $\supp{u} \cap B_{r_p}(p)$ is finite for all $p \in X$, sequence $v_n \in \LF{\mathcal{J}}{X}$ such that $\sup_n \|v_n\|_{\mathcal{J}} < 1$ and $R^{\mathcal{J}}_{\mathcal{I}}(v_n) \to u$, and $c \in (0,1)$, there exists another sequence $\tilde{v}_n \in \LF{\mathcal{J}}{X}$ such that
\begin{itemize}
\item $\|\tilde{v}_n\|_{\mathcal{J}} < 1$ for every $n \geq 1$,
\item $R^{\mathcal{J}}_{\mathcal{I}}(\tilde{v}_n) \to u$,
\item for all $p_i \in X$ and $n \geq i$, $\supp{\tilde{v}_n} \cap B_{cr_{p_i}}(p_i) \subseteq \supp{u} \cap B_{cr_{p_i}}(p_i)$.
\end{itemize}

\begin{equation} \label{eq:supp}
\tilde{v}_n \in \LF{\mathcal{J}}{Z_n}
\end{equation}

\begin{equation} \label{eq:Znj}
Z_{n,j} = B_{\rho(p_j,q)}(p_j) \cap F \subseteq \supp{u} \cap B_{cr_{p_j}}(p_j).
\end{equation}

\begin{equation} \label{eq:c=b}
\sum_{p \in X} c_{p,n}\delta_p = \sum_{\substack{(p,q) \in Z_n^2 \\ d(p,q) \leq \rho(p,q)}}b_{(p,q),n}(\delta_p-\delta_q) + \sum_{p \in Z_n} a_{p,n} \delta_p
\end{equation}
